#include <vector>
#include <cstdlib>
using namespace std;


class Solution {
public:
    ListNode* head;

    Solution(ListNode* head) {
        this->head = head;
    }

    int getRandom() {
        ListNode* curr = head;
        int result = curr->val;
        int i = 1;
        while (curr->next) {
            curr = curr->next;
            if (rand() % (++i) == 0) {
                result = curr->val;
            }
        }
        return result;
    }
};
